(() => {
 'use strict';
 if(!document.documentElement.dataset.nkRouteDocument&&!(window!==window.parent&&new URL(location.href).searchParams.has('nk_frame'))&&!new URL(location.href).searchParams.has('nk_direct'))return;
 const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
 const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const glyph=name=>'<svg viewBox="0 0 64 64" aria-hidden="true"><use href="/assets/rock-icons-v5.svg#'+name+'"/></svg>';
 const preferenceKey='noklith-appearance-v2';
 let preferences={hidden:false,finish:'sandstone'},lastFocus,toastTimer;
 const extension={actions:{},paint:null,connection:null};
 try{const p=JSON.parse(localStorage.getItem(preferenceKey)||'null');if(p)preferences={hidden:p.hidden===true,finish:['sandstone','basalt','obsidian'].includes(p.finish)?p.finish:'sandstone'}}catch{}
 // No balance or transaction records are fabricated. Account actions await a backend connection.
 const spaces=[{id:'everyday',name:'Everyday',icon:'sun',description:'For wherever today takes you.'},{id:'rent',name:'Rent',icon:'shelter',description:'A foundation for the everyday.'},{id:'travel',name:'Travel',icon:'compass',description:'For the next path you take.'},{id:'reserve',name:'Reserve',icon:'cairn',description:'A little room for what comes next.'}];
 function save(){try{localStorage.setItem(preferenceKey,JSON.stringify(preferences))}catch{toast('Appearance changes last for this visit.')}}
 function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3500)}
 const dialog=$('#action-dialog');
 function open(kicker,title,html){lastFocus=document.activeElement;$('#action-kicker').textContent=kicker;$('#action-title').textContent=title;$('#action-content').innerHTML=html;if(!dialog.open)dialog.showModal();parent.postMessage({type:'nk-overlay',open:true},location.origin);$('.dialog-close').focus()}
 function connection(action='continue'){if(extension.connection)return extension.connection(action);open('YOUR KEYS. YOUR ACCOUNT.','Connect your account.','<div class="connection-rune" aria-hidden="true">'+glyph('passkey')+'</div><p>Connect your account to '+escape(action)+'.</p><p class="connection-status">Account connection is not available yet.</p><p class="fine-print">Your balances, card, and activity will appear here once your account is connected.</p><button class="button dark" data-close-dialog>BACK TO MY ACCOUNT ↗</button>')}
 function close(){dialog.close()}
 $('.dialog-close').onclick=close;dialog.addEventListener('close',()=>{parent.postMessage({type:'nk-overlay',open:false},location.origin);if(lastFocus?.isConnected)lastFocus.focus()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
 function render(){
  const balance=preferences.hidden?'••••••':'<span class="currency">$</span>0<span class="decimal">.00</span>';
  $$('[data-total-account]').forEach(e=>e.innerHTML=balance);$$('[data-card-balance]').forEach(e=>e.textContent=preferences.hidden?'••••••':'$0.00');
  $('#toggle-balances').setAttribute('aria-label',preferences.hidden?'Show balances':'Hide balances');$('#toggle-balances').setAttribute('aria-pressed',String(preferences.hidden));
  const artworks={sandstone:['sandstone-bison','Charcoal bison cave painting on sandstone','THE BISON / SANDSTONE'],basalt:['basalt-mammoth','Ivory mammoth cave painting on basalt','THE MAMMOTH / BASALT'],obsidian:['obsidian-ibex','Ochre ibex petroglyph on obsidian','THE IBEX / OBSIDIAN']};
  const artwork=artworks[preferences.finish];$$('[data-card-collection]').forEach(e=>e.textContent=artwork[2]);const card=$('#payment-card'),art=$('.card-art',card);art.src='/assets/card-art/'+artwork[0]+'.webp';art.alt=artwork[1];card.className='payment-card '+preferences.finish;
  const large=card.cloneNode(true);large.id='payment-card-large';$('#large-card-slot').replaceChildren(large);$('#card-state').textContent='Not connected';
  $('#slab-summary').innerHTML=spaces.slice(0,3).map(s=>'<button class="slab-mini" data-open-slab="'+s.id+'"><span><i>'+glyph(s.icon)+'</i>'+s.name+'</span><b>'+(preferences.hidden?'••••':'0.00')+'</b><small>USDC</small></button>').join('');
  $('#slabs-grid').innerHTML=spaces.map(s=>'<article class="slab-standing-stone"><span class="slab-icon" aria-hidden="true">'+glyph(s.icon)+'</span><span class="micro">YOUR OWN SPACE</span><h2>'+s.name+'</h2><p>'+s.description+'</p><strong>'+(preferences.hidden?'••••':'0.00')+' <small>USDC</small></strong><button class="text-link" data-open-slab="'+s.id+'">OPEN '+s.name.toUpperCase()+' ↗</button></article>').join('');
  const empty='<div class="empty-trail"><span aria-hidden="true">'+glyph('footprints')+'</span><h3>Your trail begins here.</h3><p>Connect your account to see your activity.</p><button class="text-link" data-action="connect">CONNECT ACCOUNT ↗</button></div>';
  $('#recent-activity').innerHTML=empty;$('#full-activity').innerHTML=empty;
  $('#float-toggle').setAttribute('aria-checked','false');$('#float-target-display').innerHTML='150<small>USDC target</small>';$('#float-threshold-display').textContent='40 USDC';$('#float-cap-display').textContent='500 USDC';$('#float-level').style.width='0%';$('#float-threshold-marker').style.left='26.67%';
  $('#float-target').value=150;$('#float-threshold').value=40;$('#float-cap').value=500;
  $('#payday-splits').innerHTML=[['everyday',50],['rent',30],['reserve',20]].map(([id,value],i)=>'<label class="payday-split"><span class="sr-only">Payday destination '+(i+1)+'</span><select aria-label="Payday destination '+(i+1)+'">'+spaces.map(s=>'<option value="'+s.id+'"'+(s.id===id?' selected':'')+'>'+s.name+'</option>').join('')+'</select><input type="number" min="0" max="100" step="1" value="'+value+'" aria-label="Payday allocation '+(i+1)+'"><span>%</span></label>').join('');
  $$('[data-finish]').forEach(b=>{const on=b.dataset.finish===preferences.finish;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on))});
  extension.paint?.(preferences.hidden);
 }
 const titles={overview:['Your money.<br>On solid ground.','Overview'],slabs:['Make space.<br>For your plans.','Slabs'],cards:['Ancient lines.<br>Everyday possibilities.','My card'],activity:['Every movement.<br>A clearer view.','Activity'],rules:['Your money.<br>Your natural rhythm.','My rules'],settings:['A little clarity.<br>In every detail.','Settings']};
 function setView(view,hash=true){if(!titles[view])view='overview';$$('.dash-view').forEach(e=>e.hidden=e.id!=='view-'+view);$$('[data-view]').forEach(b=>{const selected=b.dataset.view===view;b.classList.toggle('active',selected);if(b.classList.contains('nav-item')){if(selected)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')}});$('#view-heading').innerHTML=titles[view][0];$('#breadcrumb').textContent=titles[view][1];document.title=titles[view][1]+' | Noklith';if(hash)history.replaceState(null,'','#'+view);scrollTo({top:0,behavior:'instant'});if(!matchMedia('(prefers-reduced-motion: reduce)').matches)$('#view-'+view).animate([{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'none'}],{duration:260,easing:'cubic-bezier(.22,1,.36,1)'});document.dispatchEvent(new CustomEvent('noklith:viewchange',{detail:view}))}
 const actions={connect:()=>connection(),send:()=>connection('send money'),receive:()=>connection('add funds'),move:()=>connection('move money between Slabs'),'new-slab':()=>connection('create a Slab'),refill:()=>connection('refill your card'),freeze:()=>connection('manage your card'),'card-details':()=>setView('cards'),reset:()=>{preferences={hidden:false,finish:'sandstone'};save();render();toast('Your appearance preferences have been reset.')}};
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){setView(b.dataset.view);return}if(b.hasAttribute('data-close-dialog')){close();return}const act=extension.actions[b.dataset.action]||actions[b.dataset.action];if(act){act();return}if(b.dataset.openSlab){const s=spaces.find(s=>s.id===b.dataset.openSlab);connection('open your '+s.name+' Slab');return}if(b.dataset.finish){preferences.finish=b.dataset.finish;save();render();toast(b.getAttribute('aria-label')+' selected.');return}if(b.dataset.network){open('A WIDER WORLD',b.dataset.network==='More networks'?'More paths ahead.':b.dataset.network,'<p>Base is Noklith’s home network. The product architecture includes routes for Arbitrum, Ethereum, BNB Chain, Robinhood Chain, and Solana deposits.</p><p>Available networks and routes appear after your account is connected.</p><button class="button dark" data-close-dialog>BACK TO MY ACCOUNT ↗</button>')}});
 $('#toggle-balances').onclick=()=>{preferences.hidden=!preferences.hidden;save();render()};$('#float-toggle').onclick=()=>connection('enable Float');
 $('#float-form').onsubmit=e=>{e.preventDefault();connection('save and sign your Float rules')};$('#payday-form').onsubmit=e=>{e.preventDefault();connection('save your payday rule')};
 $('#payday-splits').addEventListener('input',()=>{const total=$$('#payday-splits input').reduce((n,e)=>n+Number(e.value||0),0);$('#payday-total').textContent=total+'%';$('#payday-total').classList.toggle('invalid',total!==100)});
 $('#export-csv').onclick=()=>connection('access and export your activity');
 $('#sidebar-toggle').innerHTML=glyph('carving');$('#sidebar-toggle').setAttribute('aria-label','Open settings');$('#sidebar-toggle').onclick=()=>setView('settings');window.addEventListener('hashchange',()=>setView(location.hash.slice(1),false));render();setView(location.hash.slice(1)||'overview',false);
 // Account connection (account.js) plugs in here.
 window.nkDashboard={open,close,toast,escape,glyph,render,extend:e=>{Object.assign(extension.actions,e.actions||{});extension.paint=e.paint||extension.paint;extension.connection=e.connection||extension.connection;render()}};
})();
